        rb_pool_t *p = pool_create(bad[i].obj_size);

        snprintf(msg, sizeof msg, "[pool: reject] pool_create(%s) returns NULL", bad[i].name);
        check(p == NULL, msg);

        snprintf(msg, sizeof msg,
