+{
+    size_t stride, slot0_offset, objs_per_slab, slack;
+
+    if (!rb_pool_geometry(obj_size, &stride, &slot0_offset, &objs_per_slab, &slack))
+        return NULL;
+
+    rb_pool_t *p = rb_malloc(sizeof *p);
+    if (p == NULL) return NULL;
